// Security lives in layers, not one place.
@RestController
public class TransferController {

    @PostMapping("/transfers")
    @PreAuthorize("hasRole('USER')")          // layer 3: authorization (who may do this)
    public TransferResult transfer(
            @AuthenticationPrincipal Principal user,        // layer 2: identity (who)
            @Valid @RequestBody TransferRequest req) {       // layer 4: input validated by Bean Validation

        // layer 5: secrets never live in code — read from config/Vault
        if (!rateLimiter.tryConsume(user.getName())) {
            throw new TooManyRequestsException();
        }
        // business logic runs with least privilege; sensitive ops are audited
        audit.log(user.getName(), "transfer", req.amount());
        return transferService.execute(user.getName(), req);
    }
}

// TLS terminates at the load balancer (layer 1); mTLS between services
//   is enforced by service mesh, not the app — so a misconfigured app can't
//   accidentally send secrets in cleartext.
